const localeCompare = require('@isaacs/string-locale-compare')('en')
const Arborist = require('../')
const log = require('./lib/logging.js')

module.exports = (options, time) => {
  const query = options._.shift()
  const a = new Arborist(options)
  return a
    .loadVirtual()
    .then(tree => {
      // only load the actual tree if the virtual one doesn't have modern metadata
      if (!tree.meta || !(tree.meta.originalLockfileVersion >= 2)) {
        throw 'load actual'
      } else {
        return tree
      }
    }).catch((er) => {
      log.error('loading actual tree', er)
      return a.loadActual()
    })
    .then(time)
    .then(({ result: tree }) => {
      const output = []
      if (!query) {
        const set = []
        for (const license of tree.inventory.query('license')) {
          set.push([tree.inventory.query('license', license).size, license])
        }

        for (const [count, license] of set.sort((a, b) =>
          a[1] && b[1] ? b[0] - a[0] || localeCompare(a[1], b[1])
          : a[1] ? -1
          : b[1] ? 1
          : 0)) {
          output.push(`${count} ${license}`)
          log.info(count, license)
        }
      } else {
        for (const node of tree.inventory.query('license', query === 'undefined' ? undefined : query)) {
          const msg = `${node.name} ${node.location} ${node.package.description || ''}`
          output.push(msg)
          log.info(msg)
        }
      }

      return output.join('\n')
    })
}

// This is an implementation of the validForNewPackage flag in validate-npm-package-license, which is no longer maintained

const parse = require('spdx-expression-parse')

function usesLicenseRef (ast) {
  if (Object.hasOwn(ast, 'license')) {
    return ast.license.startsWith('LicenseRef') || ast.license.startsWith('DocumentRef')
  } else {
    return usesLicenseRef(ast.left) || usesLicenseRef(ast.right)
  }
}

// license should be a valid SPDX license expression (without "LicenseRef"), "UNLICENSED", or "SEE LICENSE IN <filename>"
module.exports = function licenseValidForNewPackage (argument) {
  if (argument === 'UNLICENSED' || argument === 'UNLICENCED') {
    return true
  }
  if (/^SEE LICEN[CS]E IN ./.test(argument)) {
    return true
  }
  try {
    const ast = parse(argument)
    return !usesLicenseRef(ast)
  } catch {
    return false
  }
}
